let parsed;
try {
  parsed = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  throw new Error('Classifier Output is not valid JSON');
}
const signals = parsed.signals || [];
return signals.map(s => ({ json: s }));

let ai;
try {
  ai = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  ai = {};
}
const signal = $('Tách danh sách Signals').item.json;
return [{
  json: {
    title: signal.title,
    bottleneck: signal.bottleneck,
    exact_language: signal.exact_language,
    raw_signal: signal.raw_signal,
    content_anchor: ai.final_content_anchor || signal.exact_language,
    newsjacking_bridge: ai.newsjacking_bridge || '',
    evergreen_anchor: ai.evergreen_anchor || '',
    service_link: ai.service_link || signal.service_bridge
  }
}];

const items = $input.all();
for (const item of items) {
  let text = JSON.stringify(item.json);
  // Redact emails
  text = text.replace(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9._-]+)/gi, "[EMAIL_REDACTED]");
  // Redact phone numbers (simple VN phone regex)
  text = text.replace(/(0[3|5|7|8|9])+([0-9]{8})/g, "[PHONE_REDACTED]");
  item.json = JSON.parse(text);
}
return items;
